package main

func toolprobeMutants() []mutant {
	return []mutant{
		{name: "probe-version-cap-plus-one-admitted", file: "internal/toolprobe/toolprobe.go", replacements: []replacement{{before: `return runProbe(ctx, agentic.ProbeStageVersion, binary, env, versionArg, maxVersionBytes, versionTimeout)`, after: `return runProbe(ctx, agentic.ProbeStageVersion, binary, env, versionArg, maxVersionBytes+1, versionTimeout)`}}, testPackage: "./internal/toolprobe", testName: "TestVersionOutputCapsDuringRead", runPattern: "^TestVersionOutputCapsDuringRead$/^one-past-cap$", failureText: "want a *ProbeExecutionError", narrows: "admits exactly one excess version byte; larger answers and help bounds still refuse"},
		{name: "probe-version-overflow-waits-for-deadline", file: "internal/toolprobe/toolprobe.go", replacements: []replacement{{before: "case <-stdout.limited:\n\t\t\tbreak observe", after: "case <-stdout.limited:\n\t\t\tif stage == agentic.ProbeStageVersion { <-bounded.Done(); deadlineFired = true }\n\t\t\tbreak observe"}}, testPackage: "./internal/toolprobe", testName: "TestProbeOverflowDoesNotWaitForExecutionDeadline", runPattern: "^TestProbeOverflowDoesNotWaitForExecutionDeadline$/^version$", failureText: "overflow waited for the execution deadline", narrows: "keeps the cap and overflow token but delays version overflow teardown until the execution deadline; help overflow still wakes immediately"},
		{name: "probe-overflow-lost-on-incomplete-teardown", file: "internal/toolprobe/toolprobe.go", replacements: []replacement{{before: `if stdout.Over() {`, after: `if stdout.Over() && !incomplete {`}}, testPackage: "./internal/toolprobe", testName: "TestProbeOverflowRemainsLimitedWithUnconfirmedTeardown", runPattern: "^TestProbeOverflowRemainsLimitedWithUnconfirmedTeardown$", failureText: `want stage "version" timeout false limited true`, narrows: "preserves ordinary overflow refusals but erases the output-limited fact when teardown cannot be confirmed"},
		{name: "fixture-existing-executable-rewritten-in-place", file: "internal/execfixture/write.go", replacements: []replacement{{before: `unlock := lockExecutableWrite()`, after: `if _, err := os.Stat(path); err == nil { return os.WriteFile(path, data, mode) }; unlock := lockExecutableWrite()`}}, testPackage: "./internal/execfixture", testName: "TestExecutablePublicationReplacesInode", runPattern: "^TestExecutablePublicationReplacesInode$", failureText: "executable publication rewrote the exposed inode", narrows: "retains atomic creation but rewrites already-published fixtures in place, reopening the ETXTBSY race for replacements; this is fixture evidence, not a product-gate proof"},
	}
}
